"""Finite public-only M5 context evidence. Run from any directory; no credentials."""
import asyncio
from collections import Counter
from dataclasses import fields, is_dataclass
from decimal import Decimal
from hashlib import sha256
import json
from pathlib import Path
import sys
import time
import traceback

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT))
from src.workstation.adapter_catalog import AdapterCatalog
from src.workstation.context import ContextEngine
from src.workstation.events import AssetContext, ReferencePrice, SubscriptionKey
from src.workstation.ingestion import SupervisorConfig
from src.workstation.instruments import InstrumentQuery
from src.workstation.quality import ClockReading, evaluate
from src.workstation.recording import RecordedBatch
from src.workstation.replay import ReplayClock
from src.workstation.subscriptions import SubscriptionRegistry

OUT = Path(sys.argv[1]) if len(sys.argv) > 1 else Path(__file__).with_name("m5-live-context-results.json")


def exact(value):
    if value is None or isinstance(value, (str, bool)):
        return value
    if isinstance(value, (int, Decimal)):
        return str(value)
    if isinstance(value, float):
        return repr(value)
    if is_dataclass(value):
        return {"record_type": type(value).__name__, **{f.name: exact(getattr(value, f.name)) for f in fields(value)}}
    if isinstance(value, dict):
        return {str(k): exact(v) for k, v in value.items()}
    if isinstance(value, (tuple, list, set, frozenset)):
        return [exact(item) for item in value]
    raise TypeError(type(value).__name__)


async def probe(report):
    catalog = AdapterCatalog()
    report["discovery"] = {}

    async def discover(venue):
        start = time.time_ns()
        try:
            async with asyncio.timeout(40):
                metadata = await catalog.adapter(venue).discover()
            catalog.instruments.apply_metadata(metadata)
            report["discovery"][venue] = {
                "started_wall_ns": start, "finished_wall_ns": time.time_ns(),
                "source": metadata.source, "payload_hash": metadata.payload_hash,
                "instrument_count": len(metadata.instruments), "status": "available",
            }
        except Exception as exc:
            report["discovery"][venue] = {"status": "failed", "type": type(exc).__name__, "detail": str(exc), "reason": getattr(exc, "reason", None)}

    await asyncio.gather(*(discover(venue) for venue in ("binance-global", "hyperliquid", "coinbase")))
    instruments = catalog.instruments.list(InstrumentQuery(status="active"))
    selected = []
    missing = []
    for venue, symbols, market, quote in (
        ("binance-global", ("BTC", "ETH", "SOL"), "spot", "USDT"),
        ("hyperliquid", ("BTC", "ETH", "SOL", "HYPE"), "perpetual", None),
        ("coinbase", ("BTC",), "spot", "USD"),
    ):
        for symbol in symbols:
            matches = [item for item in instruments if item.venue == venue and item.base.ticker == symbol and item.market_type == market and (quote is None or item.quote.asset_id == quote)]
            if len(matches) == 1:
                selected.append(matches[0])
            else:
                missing.append({"venue": venue, "base": symbol, "market": market, "quote": quote, "matches": len(matches)})
    spots = [item for item in instruments if item.venue == "hyperliquid" and item.market_type == "spot" and item.base.ticker in ("HYPE", "UBTC", "UETH", "USOL", "PURR")]
    # Finite discovered native-token coverage, never a ticker-to-canonical rewrite.
    selected.extend(spots[:5])
    report["selected_metadata"] = selected
    report["missing_selection"] = missing
    report["native_spot_candidates"] = spots
    registry = SubscriptionRegistry(catalog, config=SupervisorConfig(
        ack_timeout=8, snapshot_timeout=12, valid_data_timeout=15,
        silence_timeout=15, heartbeat_interval=8, stop_drain_timeout=3,
    ))
    report["collector_session_id"] = registry.session_id
    report["collector_clock_id"] = registry.clock_id
    counters = Counter()
    raw_counts = Counter()
    raw_samples = {}
    latest_events = {}
    engine = None
    pending = []
    clock = ReplayClock()
    delivery = 0
    report["callback_errors"] = []

    def raw(frame):
        key = str(frame.stream_id)
        raw_counts[key] += 1
        samples = raw_samples.setdefault(key, [])
        if len(samples) < 3:
            samples.append({"receive_wall_ns": frame.receive_wall_ns, "receive_mono_ns": frame.receive_mono_ns, "clock_id": frame.clock_id, "endpoint_id": frame.endpoint_id, "transport": frame.transport, "payload_sha256": frame.payload_sha256, "payload_bytes": len(frame.payload), "payload_prefix_utf8": frame.payload[:16384].decode("utf-8", "replace"), "truncated": len(frame.payload) > 16384})

    def process(events, books):
        nonlocal delivery
        if engine is None:
            if len(pending) >= 256:
                raise RuntimeError("probe pending delivery bound exceeded")
            pending.append((events, books))
            return
        delivery += 1
        try:
            clock.advance(events[0])
            engine.on_batch(RecordedBatch(delivery, events), books, clock)
            for event in events:
                counters[(str(event.stream_id), type(event.payload).__name__)] += 1
                if isinstance(event.payload, (ReferencePrice, AssetContext)):
                    latest_events[str(event.stream_id)] = event
        except Exception as exc:
            if len(report["callback_errors"]) < 8:
                report["callback_errors"].append({"type": type(exc).__name__, "detail": str(exc)})
            raise

    unsub_raw = registry.subscribe_raw(raw)
    unsub_processed = registry.subscribe_processed(process)
    leases = []
    report["acquisition_failures"] = []
    report["first_eligible_basis"] = {}
    report["missing_fx_observations"] = {}
    report["first_eligible_context"] = {}
    report["first_eligible_reference"] = {}
    report["first_eligible_books"] = {}
    report["first_incompatible_native_identity"] = {}
    try:
        for instrument in selected:
            channels = ("book", "reference", "context") if instrument.venue == "hyperliquid" else ("book",)
            for channel in channels:
                try:
                    key = SubscriptionKey.for_instrument(instrument, channel=channel)
                    leases.append(await registry.acquire("m5-public-context-probe", key))
                except Exception as exc:
                    report["acquisition_failures"].append({"instrument_id": instrument.instrument_id, "channel": channel, "type": type(exc).__name__, "detail": str(exc)})
        streams = tuple(registry.describe(lease) for lease in leases)
        report["streams"] = streams
        engine = ContextEngine(streams)
        for events, books in pending:
            process(events, books)
        pending.clear()
        report["collection_started_wall_ns"] = time.time_ns()
        deadline = time.monotonic() + 45
        snapshots = {}
        while time.monotonic() < deadline:
            await asyncio.sleep(0.25)
            now = ClockReading(registry.clock_id, time.monotonic_ns(), time.time_ns())
            books = registry.books()
            for book in books:
                instrument = next(item for item in selected if item.instrument_id == book.instrument_id)
                eligibility = evaluate(book, instrument, "comparison", now)
                if eligibility.eligible:
                    report["first_eligible_books"].setdefault(str(book.instrument_id), {
                        "asof": book.asof, "quality": book.quality,
                        "top_bids": book.bids[:3], "top_asks": book.asks[:3],
                        "eligibility": eligibility,
                    })
            for instrument in selected:
                if instrument.venue != "hyperliquid":
                    continue
                snapshot = engine.snapshot(instrument.instrument_id, books=books, now=now)
                snapshots[str(instrument.instrument_id)] = snapshot
                for row in snapshot.watchlist:
                    if row.eligibility.eligible:
                        report["first_eligible_reference"].setdefault(row.stream_id, row)
                for row in snapshot.contexts:
                    if row.eligibility.eligible:
                        report["first_eligible_context"].setdefault(row.stream_id, row)
                for row in snapshot.basis:
                    identity = "|".join((row.spot_instrument_id, row.perpetual_instrument_id, row.reference_kind))
                    if not row.reasons:
                        report["first_eligible_basis"].setdefault(identity, row)
                    if any(reason.startswith("missing_fx:") for reason in row.reasons):
                        report["missing_fx_observations"].setdefault(identity, row)
                    if "incompatible_underlying_identity" in row.reasons:
                        report["first_incompatible_native_identity"].setdefault(identity, row)
        report["collection_finished_wall_ns"] = time.time_ns()
        report["final_snapshots"] = snapshots
        report["subscription_status_before_cleanup"] = registry.snapshot()
        report["engine_checkpoint_sha256"] = sha256(engine.checkpoint()).hexdigest()
    finally:
        unsub_raw()
        unsub_processed()
        try:
            async with asyncio.timeout(15):
                await registry.close()
            report["cleanup"] = {"closed": True, "remaining_subscriptions": len(registry.snapshot())}
        except Exception as exc:
            report["cleanup"] = {"closed": False, "type": type(exc).__name__, "detail": str(exc)}
        report["raw_frame_counts"] = raw_counts
        report["raw_samples"] = raw_samples
        report["decoded_payload_counts"] = {"|".join(key): count for key, count in counters.items()}
        report["latest_context_reference_events"] = latest_events
        report["deliveries"] = delivery
        report["pending_async_tasks"] = [task.get_name() for task in asyncio.all_tasks() if task is not asyncio.current_task() and not task.done()]


async def main():
    report = {"probe": "M5 actual public registry/adapters/context, no mocks or orders", "started_wall_ns": time.time_ns(), "bounds": {"discovery_seconds_per_venue": 40, "collection_seconds": 45, "cleanup_seconds": 15, "overall_seconds": 115}, "fx_rates_supplied": [], "limitations": ["Finite current observation, not a long-duration stability claim", "Open-interest unit is adapter-declared base and not independently verified from primary field-unit prose", "No signed/private endpoints, execution, funding P&L, or executable arbitrage", "Coinbase BTC-USD is additional genuine USD evidence; unavailable source remains unavailable"]}
    try:
        async with asyncio.timeout(115):
            await probe(report)
    except Exception as exc:
        report["fatal"] = {"type": type(exc).__name__, "detail": str(exc), "traceback": traceback.format_exc()}
    finally:
        report["finished_wall_ns"] = time.time_ns()
        paths = ("src/workstation/context.py", "src/workstation/quality.py", "src/workstation/adapters/hyperliquid.py", "src/workstation/adapters/binance.py", "src/workstation/subscriptions.py", "src/workstation/ingestion.py", "tests/test_workstation_hyperliquid.py", "docs/evidence/m5-live-context-probe.py")
        report["source_sha256"] = {path: sha256((ROOT / path).read_bytes()).hexdigest() for path in paths}
        OUT.write_text(json.dumps(exact(report), indent=2) + "\n")
        print(json.dumps({"evidence": str(OUT), "fatal": report.get("fatal"), "discovery": report.get("discovery"), "eligible_basis_count": len(report.get("first_eligible_basis", {})), "missing_fx_count": len(report.get("missing_fx_observations", {})), "eligible_context_count": len(report.get("first_eligible_context", {})), "eligible_reference_count": len(report.get("first_eligible_reference", {})), "eligible_books_count": len(report.get("first_eligible_books", {})), "cleanup": report.get("cleanup"), "pending_tasks": report.get("pending_async_tasks")}, default=str))


if __name__ == "__main__":
    asyncio.run(main())
